        function closeTaskModal() { document.getElementById('taskModal').classList.add('hidden'); currentWorkerId = null; currentAgentType = null; }

        async function assignTask() {
            const desc = document.getElementById('taskDescription').value.trim();
            if (!desc) { alert('Please enter a task'); return; }
            const worker = workers.find(w => w.id === currentWorkerId); if (!worker) return;
            worker.status = 'working'; renderWorkers();
            const lc = document.getElementById('logContent');
            const lid = 'loading-' + Date.now();
            lc.innerHTML += '<div class="log-entry" id="' + lid + '"><div><div class="displayName">' + worker.displayName + '</div><div class="task">' + desc + '</div></div><div class="agentType">' + worker.agentType + '</div><div class="result">Processing...</div></div>';
            lc.scrollTop = lc.scrollHeight;
            try {
                const res = await fetch('http://localhost:3000/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ message: 'You are ' + worker.displayName + ' (' + worker.agentType + '). Task: ' + desc, model: 'kr/claude-sonnet-4.5', attachments: [] }) });
                const data = await res.json();
                document.getElementById(lid).remove();
                addLogEntry(worker.displayName, worker.agentType, desc, data.response || 'Completed');
                worker.status = 'completed'; renderWorkers();
            } catch (e) { const le = document.getElementById(lid); if (le) le.innerHTML = '<div><div class="displayName">' + worker.displayName + '</div><div class="task">' + desc + '</div></div><div class="agentType">' + worker.agentType + '</div><div class="result error">Error: ' + e.message + '</div>'; worker.status = 'idle'; renderWorkers(); }
            closeTaskModal();
        }

        function addLogEntry(dn, at, t, r) {
            const e = { displayName: dn, agentType: at, task: t, result: r, resultType: (r.includes('Error') || r.includes('failed')) ? 'error' : 'success', timestamp: new Date().toISOString() };
            taskLog.unshift(e); saveToStorage(); renderLog();
        }

        function toggleLog() { const c = document.getElementById('logContent'); const b = document.querySelector('.log-toggle');
            if (c.style.maxHeight) { c.style.maxHeight = ''; b.textContent = '▼'; } else { c.style.maxHeight = '300px'; b.textContent = '▲'; } }
        function saveToStorage() { localStorage.setItem('virtualOfficeLog', JSON.stringify(taskLog)); }
        function loadFromStorage() { const s = localStorage.getItem('virtualOfficeLog'); if (s) { try { taskLog = JSON.parse(s); renderLog(); } catch (e) { console.error(e); } } }
    </script>
</body>
